import java.util.*;
class Solution {int[] a,pow;int k,n;byte[][] memo;boolean dfs(int mask,int rem){if(mask==(1<<n)-1)return rem==0;if(memo[mask][rem]!=0)return memo[mask][rem]==1;for(int i=0;i<n;i++)if((mask&(1<<i))==0&&dfs(mask|(1<<i),(rem*pow[i]+a[i])%k)){memo[mask][rem]=1;return true;}memo[mask][rem]=2;return false;}public int[] concatenatedDivisibility(int[] nums,int k){Arrays.sort(nums);a=nums;n=a.length;this.k=k;pow=new int[n];for(int i=0;i<n;i++){int p=1;for(int j=0;j<Integer.toString(a[i]).length();j++)p=p*10%k;pow[i]=p;}memo=new byte[1<<n][k];if(!dfs(0,0))return new int[0];int[] ans=new int[n];int mask=0,rem=0;for(int t=0;t<n;t++)for(int i=0;i<n;i++)if((mask&(1<<i))==0){int nr=(rem*pow[i]+a[i])%k;if(dfs(mask|(1<<i),nr)){ans[t]=a[i];mask|=1<<i;rem=nr;break;}}return ans;}}